import pathlib,json
p=pathlib.Path(__file__).parent;d=json.loads((p/'mode_control_protocol.json').read_text());rows=json.loads((p/'mode_control_test_results.json').read_text())['records'];e=d['events']
r={'records':len(rows),'modes_seen':sorted({x['mode'] for x in rows}),'stop_stable':any(x.get('stopped_stable') for x in e),'auto_lock_rejected':any(x.get('command')=='SET_MODE AUTO_LOCK' and x.get('reply')==['ERR unsupported_mode'] for x in e),'four_supported_commands_two_ack':all(len(next(x['reply'] for x in e if x.get('command')==cmd))==2 for cmd in ['STOP','START','SET_MODE BAND_SCAN','SET_MODE FIXED']),'worker_error':d.get('error'),'note':'ACK denotes control-state update; subsequent actual RF rows prove mode behavior. One in-flight frame completed after STOP before counts became stable.'}
